━━━━━━━━━━━━━━━━━━━━━━
基礎、基礎ぐい、壁、柱、小屋組、土台、斜材（筋かい・方づえ・火打材等）、床版、屋根版、横架材（はり・けた等）で、建築物の自重・積載荷重・積雪・風圧・土圧・水圧又は地震その他の震動・衝撃を支えるもの★
