        id: 'ik-ho-06', title: '一般構造規定①採光・換気', emoji: '🪟',
        body: `▼ゼロから：採光・換気規定は居室の快適性・衛生を確保する単体規定の基本です。一級建築士試験では、住宅以外の居室（病院の病室、学校の教室等）への適用や、採光補正係数の計算を伴う応用問題が出やすく、単なる暗記では対応できません。

━━━━━━━━━━━━━━━━━━━━━━
🔑 採光規定（法28条1項、令19条・20条）
━━━━━━━━━━━━━━━━━━━━━━
・住宅の居住のための居室、学校の教室、病院の病室等、用途に応じて採光に有効な開口部の床面積に対する割合（採光関係比率）が定められる★
・住宅の居室は原則1/7以上（照明設備等の設置で1/10まで緩和可）
・採光補正係数は、開口部の採光関係比率に、水平距離・垂直距離等から算出する係数を乗じて求める★
⇒ 隣地境界線からの距離や軒の出が採光補正係数に影響するため、敷地条件を絡めた計算問題が頻出。

━━━━━━━━━━━━━━━━━━━━━━
🔑 換気規定（法28条2項・3項、令20条の2）
━━━━━━━━━━━━━━━━━━━━━━
・居室には原則として換気に有効な開口部を、居室の床面積に対し1/20以上設ける★
・開口部で足りない場合は換気設備（機械換気等）の設置で代替できる
・火気使用室（調理室等）には原則として換気設備の設置義務がある（法28条3項）★
・シックハウス対策として、居室には原則として24時間換気設備の設置が義務付けられる（令20条の7・20条の8）

━━━━━━━━━━━━━━━━━━━━━━
🔑 大規模・特殊建築物での応用
━━━━━━━━━━━━━━━━━━━━━━
・病院・学校等の採光関係比率は住宅より緩和される用途があり、用途ごとの数値を比較する出題がある★
・地下街・地下室の居室は採光規定の対象外となる場合があり、換気・防災設備で代替する

【図解】採光・換気の基本割合
　区分｜必要割合｜備考
　住宅の居室の採光｜1/7（緩和で1/10）★｜照明設備設置等が条件
　居室の換気（開口部）｜1/20以上★｜不足分は機械換気で代替可
　火気使用室｜換気設備原則義務★｜排気フードや給気口の基準あり
　⚠ 採光補正係数の計算では、用途地域・方位・隣地境界線までの距離を取り違えないこと。

■ 本試験での問われ方
・「すべての居室の採光は1/7以上必要」→ ×。用途により割合が異なる。
・「換気に有効な開口部がなければ居室として使用できない」→ ×。機械換気設備で代替可能。

★ここだけ暗記
・採光は原則1/7（緩和で1/10）、換気は原則1/20、火気使用室は換気設備原則義務。
・採光補正係数は用途地域・隣地距離・軒の出で変動する。
・シックハウス対策の24時間換気は居室全般に義務付け。`,
