━━━━━━━━━━━━━━━━━━━━━━
・特別避難階段の付室・バルコニーには、別途、排煙上有効な開口部または排煙設備（加圧防排煙を含む）を設ける規定がある（令123条3項）★
・加圧防排煙システムは近年の大規模建築物で採用が増えており、一級建築士試験でも出題実績がある

【図解】排煙設備の設置義務の判断軸
　軸｜基準
　用途★｜特殊建築物で延べ面積500㎡超
