        id: 'ik-ho-17', title: '用途地域制度の全体像', emoji: '🗺️',
        body: `▼ゼロから：用途地域は、都市計画法に基づき指定される13種類の地域で、それぞれに建てられる建築物の用途が建築基準法別表第二で制限されます。一級建築士試験では、13種類を混同せず、用途制限の厳しさの序列を体系的に理解することが求められます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 用途地域の13種類
━━━━━━━━━━━━━━━━━━━━━━
・住居系（8種）：第一種低層住居専用地域、第二種低層住居専用地域、第一種中高層住居専用地域、第二種中高層住居専用地域、第一種住居地域、第二種住居地域、準住居地域、田園住居地域★
・商業系（2種）：近隣商業地域、商業地域
・工業系（3種）：準工業地域、工業地域、工業専用地域
⇒ 低層住居専用地域が最も用途制限が厳しく、工業専用地域が住宅を建てられない点で特殊、という両極端を軸に中間を位置づけると覚えやすい。

━━━━━━━━━━━━━━━━━━━━━━
🔑 用途制限の基本構造（法48条・別表第二）
━━━━━━━━━━━━━━━━━━━━━━
・別表第二は地域ごとに「建築できないもの」を列挙する形式（原則建築可、例外的に不可を列挙）★
・低層住居専用地域に近いほど制限が厳しく、商業地域・工業専用地域に近いほど制限が緩い（ただし工業専用地域は住宅が建てられない特殊な地域）

━━━━━━━━━━━━━━━━━━━━━━
🔑 特別用途地区・特定用途制限地域
━━━━━━━━━━━━━━━━━━━━━━
・特別用途地区（法49条）：用途地域の指定を補完し、地方公共団体の条例で用途制限を強化または緩和できる★
・特定用途制限地域（法49条の2）：用途地域が定められていない土地の区域で、必要な用途制限を定める

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地が2つの用途地域にまたがる場合（法91条）
━━━━━━━━━━━━━━━━━━━━━━
・建築物の敷地が2つの用途地域にわたる場合、その敷地の過半の属する地域の用途制限を敷地全体に適用する★
⇒ 「過半」が判断基準であり、面積の大小で適用する地域が決まる点を押さえる。

【図解】用途地域の厳しさの序列（イメージ）
　系統｜代表例｜傾向
　住居系★｜第一種低層住居専用地域｜制限が最も厳しい
　商業系★｜商業地域｜制限が緩く高容積率
　工業系★｜工業専用地域｜住宅建築不可という特殊な制限
　⚠ 用途地域の指定と容積率・建蔽率の指定は連動するが、別個の都市計画決定事項である。

■ 本試験での問われ方
・「敷地が2地域にまたがる場合は厳しい方の地域の制限を適用する」→ ×。用途制限は過半の属する地域（容積率・建蔽率は別規定で按分）。
・「工業専用地域には住宅を建てられる」→ ×。原則建築できない。

★ここだけ暗記
・用途地域は住居系8・商業系2・工業系3の計13種類。
・用途制限は別表第二で「建築できないもの」を列挙する方式。
・2地域にまたがる敷地の用途制限は過半の属する地域による（容積率・建蔽率は按分計算）。`,
