        body: `▼ゼロから：斜線制限（ik-ho-20）の緩和規定は、本試験では必ずと言っていいほど計算問題として出題されます。建築物をセットバックした場合の後退緩和、2つの前面道路がある場合の緩和を、実際の計算手順として押さえましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 セットバックによる道路斜線の後退緩和（法56条2項）
━━━━━━━━━━━━━━━━━━━━━━
・建築物の壁面を前面道路境界線から後退（セットバック）させた場合、道路の反対側境界線が、後退した距離だけさらに外側にあるものとみなして道路斜線を適用できる★
・後退距離は「建築物の各部分から道路境界線までの最小の後退距離」で判定し、出窓・庇等の後退緩和の対象外となる部分の扱いに注意
・この緩和は建築物全体ではなく、後退した部分に応じて道路斜線の起点がずれるイメージで捉える

━━━━━━━━━━━━━━━━━━━━━━
🔑 2以上の前面道路がある場合の緩和（令132条）
━━━━━━━━━━━━━━━━━━━━━━
・幅員の異なる2以上の前面道路に接する敷地では、最大幅員の道路を基準に容積率・道路斜線を算定できる範囲がある★
・狭い道路でも、広い道路の中心線から一定距離（2倍かつ35m以内）の範囲は、広い道路に面するものとみなして緩和される
・この緩和は容積率の前面道路幅員制限（ik-ho-18）にも同時に適用される点を押さえておく★

━━━━━━━━━━━━━━━━━━━━━━
🔑 隣地が公園・水面等の場合の緩和（令135条の3等）
━━━━━━━━━━━━━━━━━━━━━━
・前面道路の反対側や隣地境界線の先に公園・広場・水面・線路敷等がある場合、境界線がその幅の分だけ外側にあるものとみなして道路斜線・隣地斜線を適用できる★
・水面等の幅の全部または一部（水面は1/2など）を緩和に算入できる場合があり、対象施設によって算入割合が異なる

━━━━━━━━━━━━━━━━━━━━━━
🔑 天空率による代替確認（法56条7項）
━━━━━━━━━━━━━━━━━━━━━━
・斜線制限に適合しない計画でも、天空率（一定の測定点から見た空の割合）が、斜線制限どおりに建てた「適合建築物」の天空率以上であれば、その斜線制限は適用しないとすることができる★
・天空率はCADソフト等で算出するのが一般的だが、試験では考え方（高い建物でも壁面後退や形状の工夫で天空率を確保できる）の理解が問われる

【図解】斜線制限の主な緩和の起点
　緩和｜みなす内容
　セットバック★｜後退距離だけ道路の反対側境界線が外側にあるとみなす
　2以上の前面道路★｜狭い道路の一定範囲を広い道路とみなす
　公園・水面等★｜境界線がその幅の分だけ外側にあるとみなす
　⚠ 後退緩和は「後退した距離」がそのまま斜線の起点移動量になる、という対応関係を外さないこと。

■ 本試験での問われ方
・「セットバックしても道路斜線の起点は変わらない」→ ×。後退距離分だけ起点がみなし移動する。
・「天空率による確認では、道路斜線・隣地斜線・北側斜線のすべてを個別に満たす必要がある」→ ×。天空率で代替すれば個別の斜線形状への適合は不要。

★ここだけ暗記
・セットバックは後退距離の分だけ道路の反対側境界線を外側にみなす緩和。
・2以上の前面道路では、広い道路の2倍かつ35m以内の範囲を広い道路側とみなせる。
・天空率による確認は、斜線制限そのものを個別に満たさなくても適合扱いにできる代替手段。`,
