        body: `▼ゼロから：ik-ho-06で換気規定の全体像を扱いましたが、機械換気設備そのものの構造基準（令20条の2・129条の2の5）は法規科目で独立したテーマとして出題されます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 機械換気設備の技術基準（令129条の2の5）
━━━━━━━━━━━━━━━━━━━━━━
・換気設備は、換気上有効な給気機・排気機・給気口・排気口等により構成し、換気経路に必要な換気量を確保できる能力を持たせる★
・中央管理方式の空気調和設備（大規模建築物の全館空調）を用いる場合は、別途、浮遊粉じん量・一酸化炭素含有率・温度・相対湿度・気流等の基準に適合させる

━━━━━━━━━━━━━━━━━━━━━━
🔑 シックハウス対策の技術基準（令20条の7・20条の8）
━━━━━━━━━━━━━━━━━━━━━━
・居室には原則として、1時間あたり居室の容積の0.5回以上の換気量を確保できる機械換気設備（24時間換気）の設置が義務付けられる★
・ホルムアルデヒドを発散する建築材料の使用面積には制限があり、第1種・第2種・第3種の発散速度区分に応じて使用できる面積が異なる
・天井裏等にホルムアルデヒドを発散する材料を用いる場合は、気密層・通気止め等の措置、または換気設備の措置が必要

━━━━━━━━━━━━━━━━━━━━━━
🔑 火を使用する室の換気設備（令20条の3）
━━━━━━━━━━━━━━━━━━━━━━
・調理室等の火気使用室は、原則として換気設備を設け、排気フード・給気口の有効断面積等に基準がある★
・密閉式燃焼器具のみを設けた室等、一定の条件下では換気設備の設置義務が緩和される場合がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 中央管理方式空気調和設備との関係
━━━━━━━━━━━━━━━━━━━━━━
・大規模なオフィスビル・百貨店等では、各居室ごとの換気ではなく建物全体を一括管理する中央管理方式が採用されることが多い★
・この場合、建築物衛生法（いわゆるビル管理法）の対象になる延べ面積要件（特定建築物3000㎡以上等）とも関連して出題されることがある

【図解】換気設備関連の基準
　区分｜基準の軸
　機械換気設備の能力★｜必要換気量を確保できる給気・排気能力
　シックハウス対策★｜0.5回/時以上の換気量、建材の発散速度区分
　火気使用室の換気★｜排気フード・給気口の断面積
　⚠ シックハウス対策の24時間換気は「居室全般」が対象で、火気使用室の換気設備とは別の規定である。

■ 本試験での問われ方
・「24時間換気設備は火気使用室にのみ設置義務がある」→ ×。居室全般が原則対象。
・「ホルムアルデヒド発散建材の使用に面積制限はない」→ ×。発散速度区分に応じて使用面積が制限される。

★ここだけ暗記
・シックハウス対策の機械換気は居室の容積の0.5回/時以上が目安。
・ホルムアルデヒド発散建材は発散速度区分により使用面積が制限される。
・火気使用室の換気設備は排気フード・給気口の断面積等、別個の技術基準を持つ。`,
