━━━━━━━━━━━━━━━━━━━━━━
・労働基準法は労働時間・賃金・休日等、労働条件の最低基準を定める法律★
・労働安全衛生法はそこから分離独立した法律で、労働災害の防止、職場の安全衛生の確保を目的とする
・建設工事現場では、労働基準法（労働時間管理等）と労働安全衛生法（墜落防止・資格者配置等）の両方が同時に適用される

━━━━━━━━━━━━━━━━━━━━━━
