━━━━━━━━━━━━━━━━━━━━━━
・足場の組立て等作業主任者、型枠支保工の組立て等作業主任者、コンクリート造の工作物の解体等作業主任者など、危険性の高い作業には資格を有する作業主任者の選任が義務付けられる★
