        body: `▼ゼロから：天空率（法56条7項）は、斜線制限（道路・隣地・北側）を数値計算によって「同等以上の採光・通風環境」を証明することで適用除外とする、一級建築士試験の頻出かつ計算の絡む制度です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 天空率の基本的な考え方
━━━━━━━━━━━━━━━━━━━━━━
・天空率は、ある測定点から見上げたときに空が占める割合を数値化したもの★
・計画建築物の天空率が、斜線制限どおりに建てた想定建築物（適合建築物）の天空率以上であれば、斜線制限は適用されない

━━━━━━━━━━━━━━━━━━━━━━
🔑 測定点の設定
━━━━━━━━━━━━━━━━━━━━━━
・道路斜線では前面道路の反対側の境界線上、隣地斜線・北側斜線では隣地境界線からの一定距離の位置に、それぞれ測定点が設定される★
・測定点は一定間隔で複数設定され、すべての測定点で適合建築物以上の天空率を満たす必要がある

【図解】天空率の仕組み
　要素｜内容
　適合建築物★｜斜線制限どおりに建てた仮想の建築物
　計画建築物★｜実際に建てようとする建築物
　判定基準｜計画建築物の天空率 ≧ 適合建築物の天空率（全測定点）★
　⚠ 天空率は道路斜線・隣地斜線・北側斜線それぞれ独立して判定する。一つの斜線制限だけ緩和されるケースもある。

■ 本試験での問われ方
・「天空率を使えば高さ制限そのものが撤廃される」→ ×。斜線制限の適用が除外されるだけで、絶対高さ制限等は別途適用される。
・「天空率は1つの測定点だけで判定する」→ ×。複数の測定点すべてで基準を満たす必要がある。

★ここだけ暗記
・天空率は計画建築物の天空率が適合建築物以上であれば斜線制限を適用除外とする制度。
・道路・隣地・北側の各斜線で独立して判定する。`,
