        body: `▼ゼロから：建築物における衛生的環境の確保に関する法律（通称ビル管理法）は、建築確認とは別の「維持管理」段階を規律する法律で、一定規模以上の建築物の環境衛生管理を義務付けます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 特定建築物の指定
━━━━━━━━━━━━━━━━━━━━━━
・興行場、百貨店、集会場、事務所等の用途で、延べ面積が一定規模（3000㎡超が目安、学校は8000㎡超）を超えるものは「特定建築物」として指定される★
・特定建築物の所有者等は、建築物環境衛生管理技術者を選任し、空気環境・給排水の管理基準を遵守する義務がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築確認との関係
━━━━━━━━━━━━━━━━━━━━━━
・ビル管理法は建築確認の審査対象（建築基準関係規定）には含まれず、建築物が使用開始された後の維持管理段階を規律する点が建築基準法の多くの規定と異なる★
・空気環境の基準（温度・湿度・CO2濃度等）、給水の水質基準等が具体的に定められる

【図解】ビル管理法の位置づけ
　項目｜内容
　対象★｜特定建築物（延べ面積3000㎡超等）
　規律段階｜使用開始後の維持管理（確認審査とは別）★
　管理者｜建築物環境衛生管理技術者の選任義務★
　⚠ 建築基準法の多くの規定が「建築時」の基準であるのに対し、ビル管理法は「使用中」の衛生管理を規律する点が特徴。

■ 本試験での問われ方
・「ビル管理法は建築確認の審査対象である」→ ×。使用開始後の維持管理を規律する別法令。
・「特定建築物には環境衛生管理技術者の選任義務がある」→ ○。

★ここだけ暗記
・ビル管理法は特定建築物の使用開始後の維持管理（空気環境・給水等）を規律し、建築確認の審査対象ではない。`,
