━━━━━━━━━━━━━━━━━━━━━━
・公共下水道の処理区域内では、汚水を公共下水道に接続することが原則として義務付けられる（下水道法11条の3）★
・処理区域外では、建築基準法の規定に基づき、便所を水洗便所とし汚水管を公共下水道以外の処理施設（浄化槽等）に連結する

【図解】給排水をめぐる法令の役割分担
　法令｜役割
　水道法★｜給水装置の構造・材質基準
　下水道法★｜処理区域内での公共下水道接続義務
