        body: `▼ゼロから：歩行距離（ik-ho-12参照）は、単に「30〜60m」という数値を覚えるだけでなく、重複距離の考え方とあわせて計算問題として出題されることがあります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 歩行距離の基本と重複距離
━━━━━━━━━━━━━━━━━━━━━━
・2以上の直通階段が設けられている場合、居室の各部分から、異なる2つの階段に至る経路が重複する区間（重複区間）の長さにも上限がある（重複距離）★
・重複距離の上限は、歩行距離の上限の1/2とされるのが基本的な考え方

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算の考え方（例）
━━━━━━━━━━━━━━━━━━━━━━
・耐火構造・内装不燃化等により歩行距離の上限が50mとなる用途・構造の場合、重複距離の上限は原則として50×1/2＝25mとなる★
・居室の最も奥の点から、2方向の階段への経路が分岐する地点までの距離が、この重複距離の上限以内である必要がある

【図解】歩行距離と重複距離の関係
　項目｜内容
　歩行距離の上限★｜用途・構造により30〜60m
　重複距離の上限★｜歩行距離上限のおおむね1/2
　判定方法｜居室の最奥点から経路分岐点までの距離で確認★
　⚠ 重複距離は「2方向避難がどこまで共通経路に頼っているか」を測る指標であり、歩行距離とは別に確認が必要な論点である。

■ 本試験での問われ方
・「重複距離の上限は歩行距離の上限と同じ数値である」→ ×。おおむね1/2とされる。
・「重複距離は1方向避難の建築物にも適用される」→ ×。2以上の直通階段がある場合の経路分岐を前提とする考え方。

★ここだけ暗記
・重複距離の上限は歩行距離上限のおおむね1/2。居室奥から経路分岐点までの距離で判定する。`,
