        body: `▼ゼロから：面積区画（ik-ho-11参照）の計算では、スプリンクラー設置による緩和の考え方を正しく適用できるかが問われます。具体例で確認しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 スプリンクラー設置による緩和の計算
━━━━━━━━━━━━━━━━━━━━━━
・自動式のスプリンクラー設備等を設置した部分の床面積は、その部分の床面積の1/2に相当する面積を、区画面積の算定上除いて計算できる（令112条4項等の趣旨）★
・耐火建築物等で原則1500㎡ごとの区画が必要な場合、スプリンクラー設置部分があれば、実質的に区画可能な床面積を大きく取れる

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例
━━━━━━━━━━━━━━━━━━━━━━
・ある階の床面積が2400㎡で、全体にスプリンクラー設備を設置した耐火建築物の場合、算定上の床面積は2400－(2400×1/2)＝1200㎡となり、1500㎡以内の区画基準を満たす（区画を新設しなくてよい）★
・部分的にスプリンクラーを設置した場合は、設置部分のみ1/2を除いて算定し、未設置部分は全数を算入する

【図解】緩和計算の考え方
　条件｜算定床面積
　スプリンクラー未設置｜床面積の全数を算入
　スプリンクラー設置部分★｜当該部分の床面積×1/2を算入（1/2を除く）
　⚠ 緩和は「区画をしなくてよい」という結論に直結するとは限らず、算定結果が基準値（1500㎡等）を超えていれば区画が必要になる。

■ 本試験での問われ方
・「スプリンクラー設置部分は床面積の算定から全額除外される」→ ×。1/2を除く（1/2は算入される）。
・「部分設置の場合は建築物全体の床面積が緩和対象になる」→ ×。設置部分のみが緩和対象。

★ここだけ暗記
・スプリンクラー設置部分は床面積の1/2を区画算定から除外できる。未設置部分・部分設置の扱いを混同しないこと。`,
