        body: `▼ゼロから：容積率・建蔽率には「最高限度」のイメージが強いですが、都市計画では「最低限度」を定めることもできます。小さすぎる建築物・敷地の乱立を防ぐための規定です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 容積率の最低限度（法52条1項等）
━━━━━━━━━━━━━━━━━━━━━━
・用途地域の都市計画で、容積率の最低限度を定めることができる場合がある（高度利用地区等、ik-ho-64参照）★
・土地の高度利用を図るべき地区で、低容積率の小規模建築物の立地を抑制する目的で用いられる

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地面積の最低限度（法53条の2）
━━━━━━━━━━━━━━━━━━━━━━
・用途地域に関する都市計画で、建築物の敷地面積の最低限度を定めることができる（200㎡を超えない範囲）★
・敷地の細分化（ミニ開発）による住環境の悪化を防ぐ目的で指定される
・既存の敷地がこれに満たない場合は、原則として既存の敷地のまま建て替えできる（遡及適用の例外）が、分割等には制限がかかる

【図解】最低限度規定の目的対比
　規定｜目的
　容積率の最低限度★｜高度利用を図るべき地区での低利用の抑制
　敷地面積の最低限度★｜敷地の細分化（ミニ開発）の防止
　⚠ 敷地面積の最低限度は200㎡を超えて定めることはできない（法53条の2第1項ただし書等の上限）。

■ 本試験での問われ方
・「敷地面積の最低限度は300㎡まで定めることができる」→ ×。200㎡を超えない範囲で定める。

★ここだけ暗記
・容積率の最低限度は高度利用促進、敷地面積の最低限度（200㎡以内）はミニ開発防止が目的。`,
