        body: `▼ゼロから：建築基準法の多くの規定は、特定行政庁（市町村長または都道府県知事）が、地域の実情に応じて区域を指定したり、個別に許可・認定を行ったりする裁量的な仕組みを随所に持っています。この「特定行政庁の指定・許可」という構造を押さえておくと条文の読み方が安定します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 特定行政庁の指定が関わる主な場面
━━━━━━━━━━━━━━━━━━━━━━
・接道義務の例外（法43条2項）、中間検査の特定工程の指定（法7条の3）、日影規制の対象区域・規制値（条例による指定を前提に法56条の2が適用）等、多数の場面で特定行政庁の裁量的関与がある★
・総合設計制度、一団地の総合的設計制度等の許可・認定も特定行政庁が主体となる

━━━━━━━━━━━━━━━━━━━━━━
🔑 試験対策上の読み方
━━━━━━━━━━━━━━━━━━━━━━
・「特定行政庁が〜と認める場合」という条文は、全国一律の数値基準ではなく、個別の判断に委ねられていることを意味する★
・このタイプの条文は、暗記すべき数値そのものより「誰が」「どのような手続で」判断するかという構造を問う出題が多い

【図解】特定行政庁が関わる代表的な制度
　制度｜関与の内容
　接道義務の例外★｜建築審査会の同意を得て許可
　総合設計制度★｜許可により容積率等を緩和
　一団地の総合的設計制度★｜認定により複数敷地を1敷地とみなす
　⚠ 「特定行政庁」と「指定確認検査機関」は別の主体であり、許可・認定の多くは指定確認検査機関には委任されていない点に注意。

■ 本試験での問われ方
・「総合設計制度の許可は指定確認検査機関が行うことができる」→ ×。特定行政庁が許可権者である。

★ここだけ暗記
・建築基準法には特定行政庁の個別の指定・許可・認定に委ねる条文が多数あり、「誰が判断するか」を正確に押さえることが重要。`,
